// The About window, laid out like Adobe's: a branded header over a tab rail
// (About, Credits, Licence). Credits lists the research and references the
// runtime was built from, the fonts and icons we ship, and every crate in
// the shipped binaries, read from assets/credits.tsv (generated by
// `cargo xtask credits` and checked by `cargo xtask ci`, so it cannot drift
// from Cargo.lock).

use std::sync::OnceLock;

use egui::{Align, Color32, FontId, Layout, Rect, RichText, Sense, Stroke, Ui, pos2, vec2};

use egui::ScrollArea;

use crate::discord::GITHUB;

/// The project site: downloads, docs and tutorials.
const WEBSITE: &str = "https://ayatsuri-2d.org";
/// Where people can support the project, if they want to: optional, and
/// nothing in the app depends on it.
pub(crate) const SUPPORT: &str = "https://buymeacoffee.com/ayatsuri2d_alterion";
use crate::panels::{EditorUi, WashKey, dithered_wash};
use crate::theme;

const W: f32 = 660.0;
const H: f32 = 470.0;
const HEADER: f32 = 112.0;

#[derive(Clone, Copy, PartialEq, Eq, Default)]
enum Tab {
    #[default]
    About,
    Credits,
    Licence,
}

#[derive(Default)]
pub(crate) struct AboutState {
    tab: Tab,
    search: String,
    wash: Option<(WashKey, egui::TextureHandle)>,
    /// Where the window sits (its centre) once dragged by the header.
    pos: Option<egui::Pos2>,
}

impl AboutState {
    pub(crate) fn open_tab(&mut self, name: &str) {
        self.tab = match name {
            "credits" => Tab::Credits,
            "licence" | "license" => Tab::Licence,
            _ => Tab::About,
        };
    }
}

struct Crate {
    name: String,
    version: String,
    licence: String,
    link: String,
}

fn crates() -> &'static [Crate] {
    static LIST: OnceLock<Vec<Crate>> = OnceLock::new();
    LIST.get_or_init(|| {
        include_str!(concat!(env!("CARGO_MANIFEST_DIR"), "/../../assets/credits.tsv"))
            .lines()
            .filter(|l| !l.starts_with('#') && !l.trim().is_empty())
            .map(|l| {
                let mut f = l.split('\t').map(str::to_string);
                Crate {
                    name: f.next().unwrap_or_default(),
                    version: f.next().unwrap_or_default(),
                    licence: f.next().unwrap_or_default(),
                    link: f.next().unwrap_or_default(),
                }
            })
            .collect()
    })
}

