impl EditorUi {
    pub(crate) fn about_window(&mut self, ui: &mut Ui) {
        if !self.show_about {
            return;
        }
        let ctx = ui.ctx().clone();
        crate::windows::mark_shown(&ctx);
        let logo = self.logo_texture(&ctx);
        let logo_size = self.logo.as_ref().map(|c| c.handle.size_vec2()).unwrap_or(vec2(1.0, 1.0));
        let gpu = self.gpu;
        let mut open = true;
        egui::Window::new(crate::i18n::tr("About Ayatsuri2D"))
            .title_bar(false)
            // only the header strip moves it; egui's own drag-anywhere
            // fought the pinned position and snapped back
            .movable(false)
            .collapsible(false)
            .resizable(false)
            .fixed_size(vec2(W, H))
            .frame(egui::Frame::window(ui.style()).inner_margin(0.0).stroke(Stroke::NONE))
            .pivot(egui::Align2::CENTER_CENTER)
            .current_pos(self.about.pos.unwrap_or(ctx.content_rect().center()))
            .show(&ctx, |ui| {
                ui.set_min_size(vec2(W, H));
                let full = ui.max_rect();
                let header = Rect::from_min_size(full.min, vec2(W, HEADER));
                // the branded header is the handle; the close button sits
                // on top of it and still takes its click
                let drag = ui.interact(header, ui.id().with("about-drag"), Sense::drag());
                if drag.dragged() {
                    let at = self.about.pos.unwrap_or(ctx.content_rect().center());
                    self.about.pos = Some(at + drag.drag_delta());
                }
                self.about_header(ui, header, logo, logo_size, &mut open);

                let body = Rect::from_min_max(pos2(full.min.x, header.max.y), full.max);
                let rail = Rect::from_min_size(body.min, vec2(132.0, body.height()));
                ui.painter().rect_filled(rail, 0.0, theme::pal().panel_bg);
                let mut rail_ui =
                    ui.new_child(egui::UiBuilder::new().max_rect(rail.shrink2(vec2(8.0, 12.0))));
                for (tab, label) in
                    [(Tab::About, "About"), (Tab::Credits, "Credits"), (Tab::Licence, "Licence")]
                {
                    let on = self.about.tab == tab;
                    let (r, resp) = rail_ui
                        .allocate_exact_size(vec2(rail_ui.available_width(), 28.0), Sense::click());
                    if on || resp.hovered() {
                        rail_ui.painter().rect_filled(
                            r,
                            4.0,
                            if on { theme::pal().select } else { theme::pal().header },
                        );
                    }
                    if on {
                        rail_ui.painter().rect_filled(
                            Rect::from_min_size(r.min + vec2(0.0, 6.0), vec2(2.0, 16.0)),
                            1.0,
                            theme::pal().accent,
                        );
                    }
                    rail_ui.painter().text(
                        r.left_center() + vec2(12.0, 0.0),
                        egui::Align2::LEFT_CENTER,
                        crate::i18n::tr(label),
                        FontId::proportional(13.0),
                        if on { theme::pal().text } else { theme::pal().text_faint },
                    );
                    if resp.clicked() {
                        self.about.tab = tab;
                    }
                    rail_ui.add_space(2.0);
                }

                let page = Rect::from_min_max(
                    pos2(rail.max.x + 20.0, body.min.y + 16.0),
                    body.max - vec2(20.0, 14.0),
                );
                let mut page_ui = ui.new_child(
                    egui::UiBuilder::new().max_rect(page).layout(Layout::top_down(Align::Min)),
                );
                match self.about.tab {
                    Tab::About => {
                        about_page(&mut page_ui, gpu, &mut self.update, &mut self.show_whats_new)
                    }
                    Tab::Credits => credits_page(&mut page_ui, &mut self.about.search),
                    Tab::Licence => licence_page(&mut page_ui),
                }
            });
        if ctx.input(|i| i.key_pressed(egui::Key::Escape)) {
            open = false;
        }
        self.show_about = open;
    }

    fn about_header(
        &mut self,
        ui: &mut Ui,
        header: Rect,
        logo: Option<egui::TextureId>,
        logo_size: egui::Vec2,
        open: &mut bool,
    ) {
        // the same dithered accent wash as the home header
        let ppp = ui.ctx().pixels_per_point();
        let key = WashKey {
            w: (header.width() * ppp).round().max(1.0) as u32,
            h: (header.height() * ppp).round().max(1.0) as u32,
            base: theme::pal().header.to_array(),
            accent: theme::pal().accent.to_array(),
        };
        if self.about.wash.as_ref().is_none_or(|(k, _)| *k != key) {
            let tex = ui.ctx().load_texture(
                "about-wash",
                dithered_wash(&key),
                egui::TextureOptions::NEAREST,
            );
            self.about.wash = Some((key, tex));
        }
        let p = ui.painter();
        match &self.about.wash {
            Some((_, tex)) => p.image(
                tex.id(),
                header,
                Rect::from_min_max(pos2(0.0, 0.0), pos2(1.0, 1.0)),
                Color32::WHITE,
            ),
            None => p.rect_filled(header, 0.0, theme::pal().header),
        };
        let left = header.min.x + 28.0;
        match logo {
            Some(id) => {
                let h = 44.0;
                let w = h * logo_size.x / logo_size.y.max(1.0);
                p.image(
                    id,
                    Rect::from_min_size(pos2(left, header.min.y + 24.0), vec2(w, h)),
                    Rect::from_min_max(pos2(0.0, 0.0), pos2(1.0, 1.0)),
                    Color32::WHITE,
                );
            }
            None => {
                p.text(
                    pos2(left, header.min.y + 24.0),
                    egui::Align2::LEFT_TOP,
                    "Ayatsuri2D",
                    FontId::proportional(32.0),
                    theme::pal().text,
                );
            }
        }
        p.text(
            pos2(left + 2.0, header.max.y - 18.0),
            egui::Align2::LEFT_BOTTOM,
            crate::i18n::tr("Open 2D puppet studio"),
            FontId::proportional(12.5),
            theme::pal().text_faint,
        );
        p.text(
            pos2(header.max.x - 24.0, header.max.y - 18.0),
            egui::Align2::RIGHT_BOTTOM,
            crate::i18n::trf("Version {version}", &[("version", &env!("CARGO_PKG_VERSION"))]),
            FontId::proportional(12.0),
            theme::pal().text_faint,
        );
        // close, top right
        let close =
            Rect::from_center_size(header.right_top() + vec2(-20.0, 20.0), vec2(24.0, 24.0));
        let resp = ui.interact(close, ui.id().with("about-close"), Sense::click());
        if resp.hovered() {
            ui.painter().rect_filled(close, 4.0, theme::pal().select);
        }
        ui.painter().text(
            close.center(),
            egui::Align2::CENTER_CENTER,
            egui_phosphor::regular::X,
            FontId::proportional(14.0),
            theme::pal().text,
        );
        if resp.clicked() {
            *open = false;
        }
    }
}

fn heading(ui: &mut Ui, text: &str) {
    ui.label(RichText::new(text).size(13.5).strong().color(theme::pal().text));
    ui.add_space(4.0);
}

fn faint(ui: &mut Ui, text: impl Into<String>) {
    ui.label(RichText::new(text.into()).size(11.5).color(theme::pal().text_faint));
}

fn about_page(
    ui: &mut Ui,
    gpu: bool,
    update: &mut crate::update::UpdateState,
    whats_new: &mut bool,
) {
    heading(ui, crate::i18n::tr("Ayatsuri2D"));
    ui.label(crate::i18n::tr(
        "An open, native 2D puppet studio: rig, animate and run Live2D-style models, \
         with full moc3 import and export and .aom as its own format.",
    ));
    ui.add_space(14.0);
    let info = [
        ("Version", env!("CARGO_PKG_VERSION").to_string()),
        ("Platform", format!("{} {}", std::env::consts::OS, std::env::consts::ARCH)),
        (
            "Renderer",
            if gpu {
                crate::i18n::tr("wgpu (GPU)").into()
            } else {
                crate::i18n::tr("software fallback").into()
            },
        ),
        ("moc3 export", crate::i18n::trf("{from} to {to}", &[("from", &"3.0"), ("to", &"5.3")])),
        ("Crates", crate::i18n::trf("{count} open-source", &[("count", &crates().len())])),
    ];
    egui::Grid::new("about-info").num_columns(2).spacing(vec2(18.0, 6.0)).show(ui, |ui| {
        for (k, v) in &info {
            ui.label(RichText::new(crate::i18n::tr(k)).color(theme::pal().text_faint));
            ui.label(v);
            ui.end_row();
        }
    });
    ui.add_space(16.0);
    // six buttons are wider than the page in some languages: wrap them
    ui.horizontal_wrapped(|ui| {
        ui.spacing_mut().item_spacing.y = 6.0;
        if ui
            .button(format!("{}  {}", egui_phosphor::regular::GLOBE, crate::i18n::tr("Website")))
            .clicked()
        {
            ui.ctx().open_url(egui::OpenUrl::new_tab(WEBSITE));
        }
        if ui
            .button(format!(
                "{}  {}",
                egui_phosphor::regular::GITHUB_LOGO,
                crate::i18n::tr("GitHub")
            ))
            .clicked()
        {
            ui.ctx().open_url(egui::OpenUrl::new_tab(GITHUB));
        }
        if ui
            .button(format!(
                "{}  {}",
                egui_phosphor::regular::BUG,
                crate::i18n::tr("Report an issue")
            ))
            .clicked()
        {
            ui.ctx().open_url(egui::OpenUrl::new_tab(format!("{GITHUB}/issues")));
        }
        if ui
            .button(format!(
                "{}  {}",
                egui_phosphor::regular::COFFEE,
                crate::i18n::tr("Support (optional)")
            ))
            .on_hover_text(crate::i18n::tr(
                "Buy Me a Coffee. Ayatsuri2D is free and stays free; this is only if you want to",
            ))
            .clicked()
        {
            ui.ctx().open_url(egui::OpenUrl::new_tab(SUPPORT));
        }
        if ui
            .button(format!(
                "{}  {}",
                egui_phosphor::regular::SPARKLE,
                crate::i18n::tr("What's New")
            ))
            .on_hover_text(crate::i18n::tr("What changed in this version"))
            .clicked()
        {
            *whats_new = true;
        }
        crate::whats_new::discord_button(ui);
        if ui
            .button(format!("{}  {}", egui_phosphor::regular::COPY, crate::i18n::tr("Copy info")))
            .clicked()
        {
            let text = info.iter().map(|(k, v)| format!("{k}: {v}")).collect::<Vec<_>>().join("\n");
            ui.ctx().copy_text(format!("Ayatsuri2D\n{text}"));
        }
    });
    // updates: ask on request; only ever points at the release page
    ui.add_space(8.0);
    let mut notes = None;
    ui.horizontal(|ui| {
        let label = format!(
            "{}  {}",
            egui_phosphor::regular::ARROWS_CLOCKWISE,
            crate::i18n::tr("Check for updates")
        );
        if ui.add_enabled(!update.checking(), egui::Button::new(label)).clicked() {
            update.start();
        }
        if update.checking() {
            ui.spinner();
            faint(ui, crate::i18n::tr("Checking…"));
        } else if let Some(latest) = update.available().cloned() {
            ui.label(
                RichText::new(crate::i18n::trf(
                    "Ayatsuri2D {version} is available",
                    &[("version", &latest.version)],
                ))
                .color(theme::pal().accent),
            );
            crate::update::actions(ui, update, &latest);
            notes = Some(latest);
        } else {
            match &update.status {
                Some(Ok(())) => faint(ui, crate::i18n::tr("You have the latest version.")),
                Some(Err(e)) => {
                    faint(ui, crate::i18n::trf("Couldn't check: {error}", &[("error", e)]))
                }
                None => {}
            }
        }
    });
    if let Some(latest) = &notes {
        crate::update::notes(ui, latest);
    }
    ui.with_layout(Layout::bottom_up(Align::Min), |ui| {
        faint(
            ui,
            crate::i18n::tr("Clean-room: built from published specifications and permissively licensed work only."),
        );
        faint(ui, crate::i18n::tr("Made by Yoru_KenomoVT."));
    });
}

fn credits_page(ui: &mut Ui, search: &mut String) {
    ui.horizontal(|ui| {
        heading(ui, crate::i18n::tr("Credits"));
        ui.with_layout(Layout::right_to_left(Align::Center), |ui| {
            ui.add(
                egui::TextEdit::singleline(search)
                    .hint_text(format!(
                        "{}  {}",
                        egui_phosphor::regular::MAGNIFYING_GLASS,
                        crate::i18n::tr("Search")
                    ))
                    .desired_width(170.0),
            );
        });
    });
    let needle = search.to_lowercase();
    let hit = |a: &str, b: &str| {
        needle.is_empty()
            || a.to_lowercase().contains(&needle)
            || b.to_lowercase().contains(&needle)
    };
    let refs: Vec<_> = REFERENCES.iter().filter(|r| hit(r.0, r.2)).collect();
    let list: Vec<&Crate> = crates().iter().filter(|c| hit(&c.name, &c.licence)).collect();
    ScrollArea::vertical().id_salt("about-credits").auto_shrink([false, false]).show(ui, |ui| {
        if !refs.is_empty() {
            section(ui, crate::i18n::tr("Built on"));
            for (name, what, licence, link) in refs {
                credit_row(ui, name, crate::i18n::tr(licence), link, Some(crate::i18n::tr(what)));
            }
            ui.add_space(12.0);
        }
        section(ui, &crate::i18n::trf("Open-source crates ({count})", &[("count", &list.len())]));
        faint(
            ui,
            crate::i18n::tr(
                "Everything compiled into the app. Thank you to everyone who wrote them.",
            ),
        );
        ui.add_space(4.0);
        for c in list {
            credit_row(ui, &c.name, &format!("{}  ·  {}", c.version, c.licence), &c.link, None);
        }
    });
}

fn section(ui: &mut Ui, text: &str) {
    ui.label(RichText::new(text).size(11.5).strong().color(theme::pal().accent));
    ui.add_space(2.0);
}

/// One credit: the name left, licence (and version) right, the whole row a
/// link when there is one, and an optional faint line under it.
fn credit_row(ui: &mut Ui, name: &str, right: &str, link: &str, what: Option<&str>) {
    let h = if what.is_some() { 36.0 } else { 20.0 };
    let (r, resp) = ui.allocate_exact_size(vec2(ui.available_width(), h), Sense::click());
    let live = !link.is_empty();
    if live && resp.hovered() {
        ui.painter().rect_filled(r, 3.0, theme::pal().header);
    }
    let p = ui.painter();
    let top = r.min.y + 10.0;
    p.text(
        pos2(r.min.x + 4.0, top),
        egui::Align2::LEFT_CENTER,
        name,
        FontId::proportional(12.5),
        theme::pal().text,
    );
    let mut right_x = r.max.x - 6.0;
    if live {
        p.text(
            pos2(right_x, top),
            egui::Align2::RIGHT_CENTER,
            egui_phosphor::regular::ARROW_SQUARE_OUT,
            FontId::proportional(12.0),
            if resp.hovered() { theme::pal().accent } else { theme::pal().text_faint },
        );
        right_x -= 20.0;
    }
    p.text(
        pos2(right_x, top),
        egui::Align2::RIGHT_CENTER,
        right,
        FontId::proportional(11.5),
        theme::pal().text_faint,
    );
    if let Some(w) = what {
        p.text(
            pos2(r.min.x + 4.0, top + 16.0),
            egui::Align2::LEFT_CENTER,
            w,
            FontId::proportional(11.0),
            theme::pal().text_faint,
        );
    }
    if live && resp.on_hover_text(link).clicked() {
        ui.ctx().open_url(egui::OpenUrl::new_tab(link));
    }
}

fn licence_page(ui: &mut Ui) {
    heading(ui, crate::i18n::tr("Licence"));
    ui.label(crate::i18n::tr(
        "Ayatsuri2D is free software: you can redistribute it and modify it under the \
         terms of the GNU General Public License, version 3.",
    ));
    ui.add_space(6.0);
    ui.label(crate::i18n::tr(
        "Two parts are licensed more permissively on purpose, so others can build on them:",
    ));
    ui.add_space(4.0);
    egui::Grid::new("about-licences").num_columns(2).spacing(vec2(18.0, 6.0)).show(ui, |ui| {
        for (part, lic) in [
            ("Editor, runtime, renderer, importers", "GPL-3.0"),
            ("openmoc3 (the moc3 reader)", "MIT"),
            ("C ABI (ayatsuri-capi)", "Apache-2.0"),
        ] {
            ui.label(crate::i18n::tr(part));
            ui.label(RichText::new(lic).color(theme::pal().accent));
            ui.end_row();
        }
    });
    ui.add_space(12.0);
    faint(
        ui,
        crate::i18n::tr(
            "This program is distributed in the hope that it will be useful, but WITHOUT ANY \
         WARRANTY; without even the implied warranty of MERCHANTABILITY or FITNESS FOR A \
         PARTICULAR PURPOSE. See the GNU General Public License for more details.",
        ),
    );
    ui.add_space(12.0);
    ui.horizontal(|ui| {
        if ui.button(crate::i18n::tr("Read the GPL-3.0")).clicked() {
            ui.ctx().open_url(egui::OpenUrl::new_tab("https://www.gnu.org/licenses/gpl-3.0.html"));
        }
        if ui.button(crate::i18n::tr("Source code")).clicked() {
            ui.ctx().open_url(egui::OpenUrl::new_tab(GITHUB));
        }
    });
    ui.add_space(12.0);
    faint(
        ui,
        crate::i18n::tr(
            "Live2D and Cubism are trademarks of Live2D Inc. Ayatsuri2D is an independent project \
         and is not affiliated with or endorsed by Live2D Inc.",
        ),
    );
}
